centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
blank=(10,8)
# For every ray, linearly extend until another object cell; preserve the source's own arms.
objcells=set()
for r,c,col in centers:
    objcells.add((r,c))
    objcells.update([(r-1,c),(r+1,c),(r,c-1),(r,c+1)])
objcells.update([(blank[0]-1,blank[1]),(blank[0]+1,blank[1]),(blank[0],blank[1]-1),(blank[0],blank[1]+1),blank])
# Determine crossings/projections in separate layers.
hproj={}; vproj={}
for r,c,col in centers:
    for dc in [-1,1]:
        j=c+dc
        while 0<=j<19:
            if orig[r][j] != 0 and (r,j) not in {(r,c),(r,c-1),(r,c+1),(r-1,c),(r+1,c)}:
                break
            if orig[r][j]==0: hproj[(r,j)]=col
            j+=dc
    for dr in [-1,1]:
        i=r+dr
        while 0<=i<19:
            if orig[i][c] != 0 and (i,c) not in {(r,c),(r,c-1),(r,c+1),(r-1,c),(r+1,c)}:
                break
            if orig[i][c]==0: vproj[(i,c)]=col
            i+=dr
# center cells themselves also remain. For a horizontal ray crossing the blank-cross column, clear it.
for pos in list(hproj):
    if pos[1]==blank[1]: del hproj[pos]
result=[row[:] for row in orig]
for (r,c),col in hproj.items(): result[r][c]=col
for (r,c),col in vproj.items(): result[r][c]=col
print('\n'.join(' '.join(map(str,row)) for row in result))

